def compute_result(base_amount, applied_codes, all_discounts):
    final_amount = base_amount
    invalid_codes = []

    for code in applied_codes:
        try:
            final_amount -= all_discounts[code]
        except KeyError:
            pass

    return {'total': final_amount, 'rejected': invalid_codes}

def summarize_order(base_amount, applied_codes, all_discounts):
    result = compute_result(base_amount, applied_codes, all_discounts)
    report = {
        'final_total': result['total'],
        'rejected_codes': sorted(result['rejected'])
    }
    return report
```

